from html.parser import HTMLParser

class TableParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.in_table = False
        self.in_row = False
        self.in_cell = False
        self.row = []
        self.cell_data = ''
        self.rows = []
        self.ranking = False

    def handle_starttag(self, tag, attrs):
        if tag == 'table' and any('wikitable' in dict(attrs).get('class', '') for _ in [1]):
            self.in_table = True
        if tag == 'tr' and self.in_table:
            self.in_row = True
            self.row = []
        if tag == 'td' and self.in_row:
            self.in_cell = True
            self.cell_data = ''
        if tag == 'a':
            for attr in attrs:
                if attr[0] == 'title' and '2020 United States census' in attr[1]:
                    self.ranking = True

    def handle_endtag(self, tag):
        if tag == 'td' and self.in_cell:
            self.in_cell = False
            self.row.append(self.cell_data.strip())
        if tag == 'tr' and self.in_row:
            self.in_row = False
            if len(self.row) >= 4:
                self.rows.append(self.row)
        if tag == 'table' and self.in_table:
            self.in_table = False

    def handle_data(self, data):
        if self.in_cell:
            self.cell_data += data

with open('/tmp/wiki_cities.html', 'r') as f:
    content = f.read()

parser = TableParser()
parser.feed(content)

# Find the section with 2023 estimates (2020 Census + 2023 Estimate columns)
for i, row in enumerate(parser.rows):
    if i >= 4:  # Skip header rows
        print(f'{i}: {row}')
        if i > 55:
            break
